'use strict';
const $=s=>document.querySelector(s),message=t=>$('#message').textContent=t;let rows=[],selected=null;const checkedPapers=new Set();let batchBusy=false;
async function api(path,options){const r=await fetch(path,{credentials:'same-origin',...options});const d=await r.json();if(!r.ok)throw Error((d.error||'请求失败')+(d.code?' ['+d.code+']':''));return d}
async function load(){checkedPapers.clear();updateBatchSelection();selected=null;$('#form').hidden=true;$('#history').replaceChildren();message('读取队列…');try{const d=await api('/api/review/queue?id='+encodeURIComponent($('#profile').value));rows=d.items;$('#queue').replaceChildren();renderQueue();message('当前追踪与导入记录 '+rows.length+' 篇；不是完整文献清单。')}catch(e){message(e.message)}}
function choose(x){selected=x;$('#title').textContent=x.paper.title;$('#source').href=x.paper.url;const f=$('#form');f.hidden=false;f.reset();f.elements.targetProfile.value=$('#profile').value;for(const [k,v]of Object.entries(x.review?.current||{}))if(f.elements[k])f.elements[k].value=v;if(!x.review&&x.brief){f.elements.summaryZh.value=x.brief.brief?.[0]||'';f.elements.summaryEn.value=x.brief.brief?.[1]||'';f.elements.highlightsZh.value=(x.brief.highlights||[]).map(h=>h.label+': '+h.text[0]).join('\n');f.elements.highlightsEn.value=(x.brief.highlights||[]).map(h=>h.label+': '+h.text[1]).join('\n');f.elements.location.value='Abstract / '+(x.brief.sourceUrl||x.paper.url);}if(!x.review&&!x.brief&&x.paper.source==='Zotero'){f.elements.summaryZh.value=x.paper.draftZh;f.elements.summaryEn.value=x.paper.draftEn;f.elements.location.value=x.paper.abstract?'Zotero abstractNote（需核对原始论文摘要）':'Zotero metadata';}$('#z-abstract').hidden=!x.paper.abstract;$('#z-abstract-text').textContent=x.paper.abstract||'';$('#history').replaceChildren();for(const h of [...(x.review?.history||[])].reverse()){const a=document.createElement('article');a.textContent=h.at+' · '+h.reviewerEmail+' · '+h.status+' · '+h.reason;$('#history').append(a)}}
$('#reload').onclick=load;$('#profile').onchange=()=>{load();zoteroStatus()};$('#form').onsubmit=async e=>{e.preventDefault();if(!selected)return;const b=Object.fromEntries(new FormData(e.target));if(['published','withdrawn'].includes(b.status)&&!confirm(b.status==='published'?'将此基础说明发布到公众页面？':'撤下此条公开说明？'))return;b.pmid=selected.paper.pmid;b.revision=selected.review?.revision||0;const button=e.target.querySelector('button');button.disabled=true;try{await api('/api/review/save?id='+encodeURIComponent($('#profile').value),{method:'POST',headers:{'content-type':'application/json','x-atlas-review':'1'},body:JSON.stringify(b)});await load();message('审核决定已保存，历史记录已保留。')}catch(e){message(e.message)}finally{button.disabled=false}};
(async()=>{try{const me=await api('/api/review/me');$('#identity').textContent='已验证审核者：'+me.user.email;const profiles=await (await fetch('/profiles.json')).json();for(const p of profiles){const o=document.createElement('option');o.value=p.id;o.textContent=p.zh+' / '+p.en;$('#profile').append(o);$('#target-profile').append(o.cloneNode(true));$('#batch-target').append(o.cloneNode(true))}await load();await zoteroStatus()}catch(e){$('#identity').textContent=e.message;message('请通过网站登录入口使用已授权账号。')}})();

async function zoteroStatus(){try{const c=await api('/api/review/zotero/status');$('#z-library').value=c.libraryId;$('#z-collection').value=c.collections[$('#profile').value]||'';$('#z-status').textContent=c.connected?'已配置云端连接；当前病毒'+(c.collections[$('#profile').value]?'已映射分类。':'尚未映射分类。'):'尚未绑定。请填写 User ID、只读 API Key 和分类标识。'}catch(e){$('#z-status').textContent=e.message}}
async function zoteroAction(action){const buttons=[$('#z-connect'),$('#z-sync')];buttons.forEach(b=>b.disabled=true);$('#z-status').textContent='正在'+(action==='sync'?'同步…':'验证连接…');try{const body={id:$('#profile').value};if(action==='connect')Object.assign(body,{libraryId:$('#z-library').value.trim(),apiKey:$('#z-key').value.trim(),collection:$('#z-collection').value.trim().toUpperCase()});const d=await api('/api/review/zotero/'+action,{method:'POST',headers:{'content-type':'application/json','x-atlas-review':'1'},body:JSON.stringify(body)});$('#z-key').value='';if(action==='sync'){await load();$('#z-status').textContent=d.status==='not_configured'?'请先配置当前病毒的分类映射。':'本次导入／更新 '+d.count+' 条，跳过重复 '+d.duplicates+' 条。'+(d.status==='partial'?'尚有记录，下次同步将继续。':'已完成本轮扫描。')+' 简介为题录草稿或摘要摘录，待人工审核。'}else await zoteroStatus()}catch(e){$('#z-status').textContent=e.message}finally{buttons.forEach(b=>b.disabled=false)}}
$('#z-connect').onclick=()=>zoteroAction('connect');$('#z-sync').onclick=()=>zoteroAction('sync');

function textElement(tag,text){const e=document.createElement(tag);e.textContent=text;return e}
function renderQueue(){for(const x of rows){const card=document.createElement('article');card.className='queue-card';const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.className='paper-check';checkbox.dataset.pmid=x.paper.pmid;checkbox.setAttribute('aria-label','选择论文：'+x.paper.title);checkbox.onchange=()=>{checkbox.checked?checkedPapers.add(x.paper.pmid):checkedPapers.delete(x.paper.pmid);card.classList.toggle('is-selected',checkbox.checked);updateBatchSelection()};const header=document.createElement('div');header.className='queue-card-header';header.append(checkbox);const b=document.createElement('button');b.textContent=(x.review?.current.status||'待审核')+' · '+x.paper.title;b.onclick=()=>choose(x);header.append(b);card.append(header);const cur=x.review?.current;card.append(textElement('p','分配到 / Assigned: '+(cur?.targetProfile?$('#target-profile option[value="'+cur.targetProfile+'"]').textContent:$('#profile').selectedOptions[0].textContent)));
const detail=document.createElement('details');detail.open=true;detail.append(textElement('summary','In brief & Highlights'));
detail.append(textElement('h3','In brief'));const zh=cur?.summaryZh||x.brief?.brief?.[0]||x.paper.draftZh||'尚无摘要解读；请打开来源并补充。';const en=cur?.summaryEn||x.brief?.brief?.[1]||x.paper.draftEn||'Summary pending source review.';detail.append(textElement('p',zh),textElement('p',en));detail.append(textElement('h3','Highlights'));const ul=document.createElement('ul');const lines=cur?.highlightsZh?[...cur.highlightsZh.split('\n'),...(cur.highlightsEn||'').split('\n')]:x.brief?.highlights?.map(h=>h.label+': '+h.text.join(' / '))||['来源：'+(x.paper.source||'论文追踪器'),'阅读依据：'+(x.paper.abstract?'已导入摘要；尚未完成解读':'仅题录，不能推断研究结果'),'研究重点与局限：待审核者补充'];for(const line of lines.filter(Boolean))ul.append(textElement('li',line));detail.append(ul,textElement('p',x.brief?'依据：已有摘要解读；仍需审核当前发布文字。':'依据：导入草稿或题录状态；不代表已审核结论。'));card.append(detail);$('#queue').append(card)}}

function updateBatchSelection(){const n=checkedPapers.size;$('#batch-count').textContent='已选择 '+n+' 篇';$('#batch-run').disabled=batchBusy||!n;for(const c of document.querySelectorAll('.paper-check')){c.checked=checkedPapers.has(c.dataset.pmid);c.closest('.queue-card').classList.toggle('is-selected',c.checked)}}
$('#batch-all').onclick=()=>{for(const x of rows)checkedPapers.add(x.paper.pmid);updateBatchSelection()};$('#batch-clear').onclick=()=>{checkedPapers.clear();updateBatchSelection()};
function batchPayload(x,status,target,reason,sourceId){const cur=x.review?.current||{};return {pmid:x.paper.pmid,revision:x.review?.revision||0,status,targetProfile:target||cur.targetProfile||sourceId,level:cur.level||'metadata',evidence:cur.evidence||'uncertain',summaryZh:cur.summaryZh||x.brief?.brief?.[0]||x.paper.draftZh||'',summaryEn:cur.summaryEn||x.brief?.brief?.[1]||x.paper.draftEn||'',highlightsZh:cur.highlightsZh||(x.brief?.highlights||[]).map(h=>h.label+': '+h.text[0]).join('\n'),highlightsEn:cur.highlightsEn||(x.brief?.highlights||[]).map(h=>h.label+': '+h.text[1]).join('\n'),location:cur.location||'',limits:cur.limits||'',publicationCheck:cur.publicationCheck||'',reason};}
$('#batch-run').onclick=async()=>{if(batchBusy)return;const chosen=rows.filter(x=>checkedPapers.has(x.paper.pmid)),sourceId=$('#profile').value,status=$('#batch-action').value,target=$('#batch-target').value,reason=$('#batch-reason').value.trim(),out=$('#batch-result');if(!chosen.length)return;if(!reason){out.textContent='请填写本次共同审核理由。';return}const payloads=chosen.map(x=>batchPayload(x,status,target,reason,sourceId));if(status==='published'){const invalid=payloads.filter(b=>b.level==='metadata'||['summaryZh','summaryEn','location','limits','publicationCheck'].some(k=>!b[k].trim()));if(invalid.length){out.textContent='尚未执行：以下 '+invalid.length+' 篇缺少已保存的摘要／全文审核资料，请逐篇补充后再批量发布：\n'+invalid.map(b=>chosen.find(x=>x.paper.pmid===b.pmid).paper.title).join('\n');return}}
const actionText=$('#batch-action').selectedOptions[0].textContent,targetText=target?$('#batch-target').selectedOptions[0].textContent:'每篇原有分配';if(!confirm('确认对 '+chosen.length+' 篇论文执行“'+actionText+'”？\n目标：'+targetText+'\n每篇将分别保存审核历史。'))return;
batchBusy=true;const locked=[...document.querySelectorAll('button,input,select,textarea')].map(e=>[e,e.disabled]);locked.forEach(([e])=>e.disabled=true);const failed=[];let successes=0;try{for(let i=0;i<payloads.length;i++){out.textContent='正在保存 '+(i+1)+' / '+payloads.length+'，已成功 '+successes+' 篇…';try{await api('/api/review/save?id='+encodeURIComponent(sourceId),{method:'POST',headers:{'content-type':'application/json','x-atlas-review':'1'},body:JSON.stringify(payloads[i])});successes++}catch(e){failed.push({pmid:payloads[i].pmid,title:chosen[i].paper.title,error:e.message})}}await load();for(const x of failed)checkedPapers.add(x.pmid);out.textContent='完成：成功 '+successes+' 篇，失败 '+failed.length+' 篇。'+(failed.length?'\n失败项目保留选择，请核对后重试：\n'+failed.map(x=>x.title+' — '+x.error).join('\n'):' 每篇审核历史已保留。')}finally{batchBusy=false;locked.forEach(([e,disabled])=>e.disabled=disabled);updateBatchSelection()}};
